mapper.select:
select count(1)
from sys_student_match
where id = #{matchId}

mapper.update:
update sys_student_match
student_profile_num = #{studentMatchUpdateDTO.studentProfileNum}, student_user_id_wecom = #{studentMatchUpdateDTO.studentUserIdWecom}, student_name_wecom = #{studentMatchUpdateDTO.studentNameWecom}, match_status = #{studentMatchUpdateDTO.matchStatus}, sync_status = #{studentMatchUpdateDTO.syncStatus}, error_msg = #{studentMatchUpdateDTO.errorMsg}, update_time = sysdate()
where id = #{studentMatchUpdateDTO.id}

UPDATE sys_parent_student_relation
SET student_name = #{sysWecomStudentNameUpdateDTO.studentName}, update_time = SYSDATE()
WHERE student_user_id = #{sysWecomStudentNameUpdateDTO.studentUserId}
